#!/bin/sh
# Start Airflow standalone (ADR-0013 §1). The simple auth manager password comes from .env
# (generated by `make env-orch`) and is written to a 0600 file; it is never printed.
set -eu
umask 077
python - <<'PY'
import json
import os

path = os.environ["AIRFLOW__CORE__SIMPLE_AUTH_MANAGER_PASSWORDS_FILE"]
with open(path, "w", encoding="utf-8") as handle:
    json.dump({"admin": os.environ["AIRFLOW_ADMIN_PASSWORD"]}, handle)
PY
umask 022
exec airflow standalone
